style.css:
@-moz-document domain("getmetastream.com") {
:root {
	--default-icon: url(https://static.vecteezy.com/system/resources/thumbnails/009/292/244/small/default-avatar-icon-of-social-media-user-vector.jpg) !important;
	--batata-icon: url(https://raw.githubusercontent.com/ap0sentada/themes-injection/refs/heads/main/icons/batata.png) !important;
	--batata-color: #9582ff !important;
}



span[title]:before {
	width: 40px !important;
	height: 40px !important;
	border-radius: 100% !important;
	display: inline-block !important;
	overflow: hidden;
	content: " ";
	margin-right: .4rem;
	background-size: contain;
	background-position: center;
	background-repeat: no-repeat;
	background-image: var(--default-icon);
}

figure img {
	opaicy: 0;
}

figure div:after {
	content: " ";
	position: absolute;
	top: 0px;
	left: 0px;
	display: block;
	width: 40px;
	height: 40px;
	background-image: var(--default-icon);
	z-index: 99;
	background-size: contain;
	background-position: center;
	background-repeat: no-repeat;
	border-radius: 50%;
}

li[class^="Chat__message"] {
    display: flex;
  	flex-wrap: wrap;
}

span[title], time{
  flex: 0 0 auto;
}
span[title] {
  order: 1;
  display: flex;
  align-content: flex-start;
  margin-right: 4px;
}
time {
  order: 2;
  display: flex;
  align-items: middle;
  transform: translateY(.2rem);
}
li span[class=""] {
  width: 100%;
  order: 3;
  margin-left: calc(0.5rem + 40px);
  transform: translatey(-1.1rem);
}

[class^="GameLobby__playbackControls_"] {
  backdrop-filter: blur(20px) !important;
}

